import os
import shutil

def permanently_delete_file(file_path):
    # Confirm the deletion of the file
    confirm = input(f"Are you sure you want to delete {file_path}? (y/n): ")
    if confirm.lower() == 'y':
        # Delete the file
        os.remove(file_path)
        print(f"{file_path} has been permanently deleted.")
    else:
        print("Deletion cancelled.")

